async def ensure_module(client):
    modules=await common.paged(client,f"/courses/{COURSE_ID}/modules"); found=next((m for m in modules if m["name"]==MODULE_NAME),None); data={"module[published]":"false"}
    if found:return await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{found['id']}",data=data)
    data["module[name]"]=MODULE_NAME; return await common.api(client,"POST",f"/courses/{COURSE_ID}/modules",data=data)

QUESTIONS=[
("Q1 - privacy","Which item stays off a middle-school résumé in this lesson?","Home address and personal phone number",["Relevant school project","True technical skill","Current school name"],"Correct. The résumé remains private and minimizes contact data.","Projects, skills, and education can be relevant; sensitive contact data is excluded."),
("Q2 - evidence","Which bullet gives the strongest evidence?","Designed two original event flyers and revised the hierarchy after teacher feedback.",["Creative","Good at Canva","Hard worker"],"Correct. It uses action, task, and revision evidence.","Traits or tool names without evidence are too vague."),
("Q3 - cue detail","Why add material and surface to an audio cue?","They help the sound worker choose or create the intended sound without guessing.",["They guarantee the movie is popular.","They replace the director.","They make every sound louder."],"Correct. Detail supports another worker's action.","Detail improves clarity; it does not guarantee outcomes or change roles."),
("Q4 - search step","What should happen before a student acts on a job-board result?","Screen the posting and verify the employer through an official route or known adult.",["Upload personal data immediately.","Message the contact in the ad.","Assume the first result is current."],"Correct. Searching and verifying are separate steps.","A result or message is not independent verification."),
("Q5 - platform","What counts as the required résumé evidence?","The truthful privacy-safe résumé in Canvas or on paper; an optional Xello copy is supplemental.",["Only an Xello completion screen","Three H&L favorites","A public Discussion post"],"Correct. The standard is the résumé, not a platform click.","Xello and H&L are not required completion tasks here, and résumés remain private."),]

async def upsert_quiz(client):
    qs=await common.paged(client,f"/courses/{COURSE_ID}/quizzes"); found=next((q for q in qs if q.get("title")==TITLES[3]),None)
    data={"quiz[title]":TITLES[3],"quiz[description]":"<p>Ungraded, unlimited-retry practice on résumé evidence, privacy, detail, and job-search safety.</p>","quiz[quiz_type]":"practice_quiz","quiz[published]":"false","quiz[allowed_attempts]":"-1","quiz[show_correct_answers]":"true","quiz[shuffle_answers]":"false"}
    quiz=await common.api(client,"PUT" if found else "POST",f"/courses/{COURSE_ID}/quizzes/{found['id']}" if found else f"/courses/{COURSE_ID}/quizzes",data=data); existing=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    for pos,(name,prompt,correct,wrong,yes,no) in enumerate(QUESTIONS,1):
        old=next((q for q in existing if q.get("question_name")==name),None); payload={"question":{"question_name":name,"question_text":prompt,"question_type":"multiple_choice_question","position":pos,"points_possible":1,"correct_comments":yes,"incorrect_comments":no,"answers":[{"answer_text":correct,"answer_weight":100}]+[{"answer_text":x,"answer_weight":0} for x in wrong]}}; path=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{old['id']}" if old else f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions"; await common.api(client,"PUT" if old else "POST",path,json=payload)
    return await common.api(client,"GET",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}")

