def teacher_content(f):
    link,flow=common.file_link,common.flow; c="#7b3f8c"
    base={1:("Behind the Microphone","d(1)(C)","A public recording is not required; protect privacy and copyright.","PODCAST","Individual five-page production plan.","Require audience, purpose, structure, three questions, access/rights plan, two careers, contribution, revision, and one popularity/income limit."),2:("Write a First Resume","d(7)(A)","Minimize personal data and never reward invented evidence.","RESUME","Private six-page résumé draft and assembly check.","Standard sections and true specific bullets matter more than graphics. Paid work is not required. Remove sensitive data before feedback."),3:("Attention to Detail and Resume Revision","d(1)(C), d(7)(A)","Students never exchange devices or logins.","DETAIL","Four cue rewrites and visible résumé before/after evidence.","Many cue answers work if safe and specific. Require visible résumé repair; trim optional peer sharing first."),4:("Seven Steps of an Effective Job Search","d(6)(A)","No real application, account, upload, employer contact, or personal data.","SEARCH","Seven-step plan, fictional posting screen, tracker, and tailored bullet.","Searching, screening, tracking, tailoring, applying, and following up are separate. A job-board result is not independent verification."),5:("Merch Mode and Final Resume Evidence","d(1)(C), d(6)(A), d(7)(A)","Minor 2 in the 6SW assessment map; original fictional brand and private résumé. Keep unpublished and ungraded until the Minor group is verified.","MERCH","Original audience-tested design plus final résumé and self-score.","Current BLS: Graphic Designers $61,300 May 2024 U.S. median, bachelor's typical, 2% 2024-34, about 20,000 annual openings. Not DFW starting pay or a guarantee.")}
    out={}
    for d,(title,teks,alert,key,evidence,monitor) in base.items():
        out[d]={"TITLE":title,"SUBTITLE":f"50 minutes · TEKS {teks}","ALERT":f"<strong>Boundary:</strong> {alert}","PREP":f'<ul><li>Post {link(f[key]["id"],"the student packet")} and the day interaction.</li><li>Open the Student Guide and matching locked workbook pages.</li><li>Keep résumé and design evidence private.</li></ul>',"EVIDENCE":f"<p>{evidence}</p>","FLOW":flow(c,"Warm-up · 5","Activate audience or evidence.")+flow("#4c8b38","Model/read · 10","One accurate example.")+flow("#1f617a","Build evidence · 20","Private fixed-source work.")+flow("#d39b22","Test/revise · 10","Add visible change and reason.")+flow(c,"Exit · 5","One conclusion and boundary."),"MONITOR":f"<p>{monitor}</p>","RESOURCES":'<p><a href="https://www.careeronestop.org/JobSearch/Resumes/resume-guide.aspx">CareerOneStop Resume Guide</a> · <a href="https://www.bls.gov/ooh/arts-and-design/graphic-designers.htm">BLS Graphic Designers</a> · <a href="https://www.irvingisd.net/departments-services/career-and-technical-education-cte/high-school-cte">Irving High School CTE</a>.</p>',"SUPPORT":"<p>Short fields hold labels only; every explanation, bullet revision, sketch, and job-search judgment has a dedicated full-width block/page. Accept typing, dictation, annotation, enlarged print, or paper.</p>","FALLBACK":"<p>Fixed packets are complete. No Xello, H&amp;L, eDynamic, public Discussion, real application, device exchange, sensitive data, or copyrighted asset is required.</p>"}
    return out

async def main():
    token=sys.stdin.readline().strip()
    if not token: raise SystemExit("Canvas token required on stdin")
    async with httpx.AsyncClient(headers={"Authorization":f"Bearer {token}"},timeout=120) as client:
        module=await ensure_module(client); path="course files/CCR Materials/6SW/Wk2"; folder=await common.ensure_folder(client,path)
        names={"PODCAST":"6sw-wk2-podcast-production-plan.pdf","RESUME":"6sw-wk2-first-resume-draft.pdf","DETAIL":"6sw-wk2-audio-cue-and-resume-revision.pdf","SEARCH":"6sw-wk2-effective-job-search.pdf","MERCH":"6sw-wk2-merch-mode-design.pdf","RUBRIC":"6sw-wk2-resume-design-rubric.pdf"}; files={k:await common.upload(client,ROOT/"docs/resources/worksheets"/n,path) for k,n in names.items()}
        vp="course files/CCR Materials/6SW/Wk2/Locked Licensed Visuals"; await common.ensure_folder(client,vp); pageset=[255,256,257,258,270,271,272,273]; visuals={f"p{n}":await common.upload(client,ASSETS/f"fyf-p{n}.jpg",vp) for n in pageset}
        quiz=await upsert_quiz(client); assignments={}
        for d,key in {1:"PODCAST",2:"RESUME",4:"SEARCH"}.items(): assignments[d]=await common.upsert_assignment(client,TITLES[d],"<p>Complete privately by annotation, upload, typed labeled responses, or paper.</p>",["student_annotation","online_upload","online_text_entry"],files[key]["id"])
        assignments[5]=await common.upsert_assignment(client,TITLES[5],"<p>Submit the private final résumé plus original Merch Mode design evidence and self-score. Keep unpublished/ungraded until the 40/60 map is verified.</p>",["online_upload","online_text_entry"],files["MERCH"]["id"])
        urls={d:f"/courses/{COURSE_ID}/assignments/{a['id']}" for d,a in assignments.items()}; urls[3]=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}"
        s,t=student_content(files,visuals,urls),teacher_content(files); labels={1:"Behind the Microphone",2:"Write a First Resume",3:"Attention to Detail and Resume Revision",4:"Seven Steps of an Effective Job Search",5:"Merch Mode and Final Resume Evidence"}; interactions={1:("Assignment",assignments[1]["id"],TITLES[1]),2:("Assignment",assignments[2]["id"],TITLES[2]),3:("Quiz",quiz["id"],TITLES[3]),4:("Assignment",assignments[4]["id"],TITLES[4]),5:("Assignment",assignments[5]["id"],TITLES[5])}; order=[]; pages={}
        for d in range(1,6):
            ht=f"Day {d} · {labels[d]}"; h=await prior.upsert_item(client,module["id"],"SubHeader",None,ht); order.append(("SubHeader",h["id"],ht)); st=f"STUDENT: 6SW Wk2 Day {d} - {labels[d]}"; sp=await common.upsert_page(client,st,common.render("6sw-wk2-student.html",{"COURSE_ID":COURSE_ID,"DAY":d,**s[d]})); tt=f"TEACHER: 6SW Wk2 Day {d} Facilitator Guide"; tp=await common.upsert_page(client,tt,common.render("6sw-wk2-teacher.html",{"COURSE_ID":COURSE_ID,"DAY":d,"STUDENT_PAGE_URL":sp["url"],**t[d]})); await prior.upsert_item(client,module["id"],"Page",tp["url"],tt); await prior.upsert_item(client,module["id"],"Page",sp["url"],st); kind,key,title=interactions[d]; await prior.upsert_item(client,module["id"],kind,key,title); order += [("Page",tp["url"],tt),("Page",sp["url"],st),(kind,key,title)]; pages[d]={"teacher":tp,"student":sp}
        items=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items")
        for pos,(kind,key,title) in enumerate(order,1):
            item=next(i for i in items if (kind=="SubHeader" and i.get("id")==key) or (kind=="Page" and i.get("page_url")==key) or (kind in ("Assignment","Quiz") and i.get("content_id")==key)); await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{module['id']}/items/{item['id']}",data={"module_item[position]":pos,"module_item[title]":title})
        final=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items"); module=await common.api(client,"GET",f"/courses/{COURSE_ID}/modules/{module['id']}"); print(json.dumps({"module":{"id":module["id"],"published":module["published"]},"folder":{"id":folder["id"],"locked":folder["locked"]},"files":{k:x["id"] for k,x in files.items()},"visuals":{k:x["id"] for k,x in visuals.items()},"quiz":{"id":quiz["id"],"published":quiz.get("published")},"assignments":{str(k):{"id":x["id"],"published":x.get("published")} for k,x in assignments.items()},"pages":{str(d):{k:{"url":x["url"],"published":x["published"]} for k,x in p.items()} for d,p in pages.items()},"items":[{"position":i["position"],"type":i["type"],"title":i["title"]} for i in final]},indent=2))

if __name__=="__main__": asyncio.run(main())
